import {validObservationDate,londonMonth} from './sightings-months.mjs';
import {buildDashboard} from './dashboard-data.mjs';
import {createSpeciesLookup,validateImages,escapeHTML as e,displayName} from './bird-cards-data.mjs';
import {validateRankings,verifyRelease} from './bird-rankings-data.mjs';
const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
let model,photos=new Map();
const trigger=item=>`<button type="button" class="bird-species-trigger" data-bird-species="${e(item.scientificName)}" aria-haspopup="dialog">${e(displayName(item.commonName,item.scientificName))}</button>`;
function photo(item,large=false){const p=photos.get(item.scientificName);return p?`<figure class="${large?'headline-photo':'movement-photo'}"><img src="${e(large?p.imageUrl:p.smallImageUrl)}" alt="${e(displayName(item.commonName,item.scientificName))}" loading="lazy"><figcaption><details><summary>Photo credit · ${e(p.licence)}</summary>${e(p.attribution)} · <a href="${e(p.sourcePage)}" target="_blank" rel="noreferrer">Commons source</a> · <a href="${e(p.licenceUrl)}" target="_blank" rel="noreferrer">${e(p.licence)}</a>. ${e(p.modifications)}${large?' Cropped to fit the headline.':''}</details></figcaption></figure>`:`<div class="photo-fallback" aria-label="No verified photograph"><img src="./icons/bird.svg" alt="" width="56" height="56"><span>Photograph unavailable</span></div>`;}
export function timelineMarkup(item){return `<div class="season-timeline" aria-label="Historical monthly reporting; A arrival, D departure">${item.pattern.map((p,i)=>`<span title="${months[i]}: ${p?`${p.records} archive records across ${p.years} years`:'historical value unavailable'}" class="${p?.records>0?'has-records':''}"><b>${months[i]}</b><small>${Number(item.arrival_month)===i+1?'A ':''}${Number(item.departure_month)===i+1?'D ':''}${p?p.records:'?'}</small></span>`).join('')}</div><p class="timeline-key">A / D: expected report-month timing · numbers: historical records. No continuous presence inferred.</p>`;}
function movementMarkup(item,direction){const expected=direction==='arrival'?item.arrival_month:direction==='departure'?item.departure_month:null;const human=item.lastReport?`Human-reported ${item.lastReport}`:'No report in the available sightings sample';const timing=expected?`${months[Number(expected)-1]} · expected ${direction}`:item.lastReport?'Reported this month':`${item.pattern[model.month-1]?.records||0} historical records this month`;
 return `<div class="row rich-movement"><div class="species" data-label="Species">${photo(item)}${trigger(item)}<span class="latin">${e(item.scientificName)}</span></div><div class="direction" data-label="Timing">${e(timing)}<small>${e(item.movement_type)} · ${e(item.confidence)} confidence</small></div><div class="window" data-label="Evidence"><span>${e(human)}</span>${item.acoustic?`<span>Acoustic detection ${e(item.acoustic.slice(0,10))} · not a human sighting</span>`:''}</div><div class="actual movement-extra" data-label="Seasonal record">${timelineMarkup(item)}</div></div>`;
}
function render(){
 const news=document.querySelector('#bird-news-grid');
 news.innerHTML=model.news.length?model.news.map((n,i)=>`<article class="news-card ${i===0?'news-lead':''}">${photo(n.item,i===0)}<div class="news-copy"><p class="eyebrow">${e(n.category)}</p><h3>${e(n.headline)}</h3><p class="news-latin"><i>${e(n.item.scientificName)}</i></p><p>${e(n.hotspot)} · <time>${e(n.date)}</time></p><p class="evidence-label">${e(n.evidence)}</p>${n.priority===1?`<p>${n.item.records} historical borough records in the available archive.</p>`:''}${n.priority<=2?`<details><summary>Why is this notable?</summary><p>${e(n.explanation)}</p></details>`:`<p>${e(n.explanation)}</p>`}${trigger(n.item)}</div></article>`).join(''):`<article class="news-card seasonal-outlook"><p class="eyebrow">Seasonal outlook</p><h3>${e(new Intl.DateTimeFormat('en-GB',{month:'long',timeZone:'Europe/London'}).format(new Date(`${model.monthKey}-15T12:00Z`)))} in the borough</h3><p>${e(model.notice)}</p><p>No supported new headline is available. Missing reports do not prove absence.</p></article>`;
 document.querySelector('#migration-context').textContent=model.notice;
 document.querySelector('#here-toggle').textContent=document.querySelector('#here-toggle').getAttribute('aria-expanded')==='true'?'Show fewer seasonal birds':`Show all ${model.here.length} seasonal birds`;
 document.querySelector('#here-toggle').hidden=model.here.length<=3;
 document.querySelector('#here-rows').innerHTML=model.here.length?model.here.map(i=>movementMarkup(i,'presence')).join(''):'<p class="empty">No safely matched seasonal evidence is available. Residents are not added to pad this view.</p>';
 for(const [id,items,direction] of [['arrivals-rows',model.arrivals,'arrival'],['departures-rows',model.departures,'departure']])document.getElementById(id).innerHTML=items.length?items.map(i=>movementMarkup(i,direction)).join(''):`<div class="empty">No validated ${direction}s for this month.</div>`;
 document.querySelector('#dashboard-summary').innerHTML=`<div><strong>${model.totals.species}</strong><span>Species reported</span></div><div><strong>${model.totals.reports}</strong><span>Species reports</span></div><div><strong>${model.totals.hotspots}</strong><span>Reporting borough hotspots</span></div><p>Latest available report: ${e(model.totals.lastRecorded||'unavailable')}. Collected sample, not a census.</p>`;
 document.querySelector('#dashboard-month').textContent=new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'Europe/London'}).format(new Date(`${model.monthKey}-15T12:00Z`));
 for(const img of document.querySelectorAll('.headline-photo img,.movement-photo img'))img.addEventListener('error',()=>{img.hidden=true;img.closest('figure').classList.add('photo-missing');});
 document.dispatchEvent(new CustomEvent('dashboard-rendered'));
}
async function boot(){try{
 const text=async file=>{const r=await fetch(`./data/${file}`,{cache:'no-store'});if(!r.ok)throw Error(file+' unavailable');return r.text();};
 const [h,r,c,m,f]=await Promise.all(['ebird-history.json','bird-rankings.json','species_migration_calendar.csv','seasonality_metadata.json','observations.json'].map(text));
 const history=JSON.parse(h),rankings=validateRankings(JSON.parse(r));await verifyRelease(rankings,m,c);
 const {parseCsvRows}=await import('./dashboard-csv.mjs');const rows=parseCsvRows(c);const headers=rows.shift();const calendar=rows.map(values=>Object.fromEntries(headers.map((key,i)=>[key,values[i]||''])));
 try{photos=validateImages(JSON.parse(await text('bird-images.json')),createSpeciesLookup(history));}catch{}
 let birdweather;try{birdweather=JSON.parse(await text('birdweather.json'));}catch{}
 const feed=JSON.parse(f);let seasonRecords=null;
 try{const index=JSON.parse(await text('sightings-archive/index.json'));if(index.schemaVersion!==1||index.source!=='eBird'||!Array.isArray(index.months))throw Error('Archive index invalid');
 const current=londonMonth(),m=Number(current.slice(5)),year=Number(current.slice(0,4)),start=m<=2?`${year-1}-12`: `${year}-${String(m===12?12:m<=5?3:m<=8?6:9).padStart(2,'0')}`;
 const entries=index.months.filter(entry=>/^\d{4}-\d{2}$/.test(entry.month)&&entry.month>=start&&entry.month<=current);
 const archives=await Promise.all(entries.map(async entry=>{const a=JSON.parse(await text(`sightings-archive/${entry.month}.json`));if(a.schemaVersion!==1||a.source!=='eBird'||a.month!==entry.month||!Array.isArray(a.records)||a.records.some(r=>!validObservationDate(r.date)||r.date.slice(0,7)!==entry.month))throw Error('Archive invalid');return a.records;}));
 seasonRecords=[...feed.records,...archives.flat()];}catch{/* Withhold first-seasonal headlines when retained coverage cannot be checked. */}
 model=buildDashboard({history,rankings,calendar,feed,seasonRecords,birdweather,publicationReady:true});render();
 }catch(error){document.querySelector('#dashboard-summary').textContent='Summary unavailable. Open detailed Actual Sightings for the last available borough feed.';document.querySelector('#here-rows').textContent='Seasonal evidence unavailable.';document.querySelector('#here-toggle').hidden=true;document.querySelector('#bird-news-grid').innerHTML='<p class="coverage-notice">Editorial highlights unavailable: the matching validated release could not be loaded. Detailed boards remain available below.</p>';document.querySelector('#migration-context').textContent='Additional seasonal context is withheld until the matching validated release is available.';}}
// Existing calendar/feed refreshes can re-render their tables. Reapply the richer
// presentation only to the published current-month migration view, never contributors.
let queued=false;const observer=new MutationObserver(()=>{if(!model||queued)return;queued=true;queueMicrotask(()=>{queued=false;observer.disconnect();render();watch();});});
function watch(){for(const id of ['arrivals-rows','departures-rows'])observer.observe(document.getElementById(id),{childList:true});}
watch();
document.addEventListener('bird-card-rendered',event=>{const item=model?.byScientific.get(event.detail.scientificName);if(!item)return;const root=document.querySelector('.bird-card-content');if(root&&!root.querySelector('.card-seasonality')){for(const p of root.querySelectorAll('p'))if(p.textContent==='Borough migration timing and historical hotspot locations are unavailable pending verification.')p.textContent='Historical hotspot locations and migration routes remain unpublished pending verification.';root.insertAdjacentHTML('beforeend',`<section class="card-seasonality"><h3>Verified borough seasonality</h3><p>${e(item.movement_type)} · ${e(item.confidence)} confidence. ${e(item.lastReport?`Borough report: ${item.lastReport}`:'No current borough report in the available sample')}.</p>${timelineMarkup(item)}<p>Routes remain unpublished pending verification.</p></section>`);}});
document.querySelector('#here-toggle').addEventListener('click',event=>{const expanded=event.currentTarget.getAttribute('aria-expanded')!=='true';event.currentTarget.setAttribute('aria-expanded',String(expanded));document.querySelector('#here-rows').classList.toggle('expanded',expanded);event.currentTarget.textContent=expanded?'Show fewer seasonal birds':`Show all ${model.here.length} seasonal birds`;});
document.querySelector('#dashboard-month').textContent=new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'Europe/London'}).format(new Date());
boot();
